<?php declare(strict_types=1); $filesystemFile=__DIR__.'/filesystem.xml'; function fsLoad():DOMDocument{ global $filesystemFile; $dom=new DOMDocument('1.0','UTF-8'); $dom->preserveWhiteSpace=false; $dom->formatOutput=true; libxml_use_internal_errors(true); if(is_file($filesystemFile)&&$dom->load($filesystemFile)){libxml_clear_errors();return $dom;} libxml_clear_errors(); $dom->appendChild($dom->createElement('filesystem')); $root=$dom->createElement('directory'); $root->setAttribute('name','/'); $dom->documentElement->appendChild($root); fsSave($dom); return $dom; } function fsSave(DOMDocument $dom):bool{ global $filesystemFile; $tmp=$filesystemFile.'.tmp'; if($dom->save($tmp)===false)return false; return rename($tmp,$filesystemFile); } function fsRoot(DOMDocument $dom):DOMElement{ foreach($dom->documentElement->childNodes as $node){ if($node instanceof DOMElement&&$node->tagName==='directory'&&$node->getAttribute('name')==='/')return $node; } $root=$dom->createElement('directory'); $root->setAttribute('name','/'); $dom->documentElement->appendChild($root); fsSave($dom); return $root; } function fsParts(string $path):array{ $path=str_replace('\\','/',trim($path)); $parts=[]; foreach(explode('/',$path) as $part){ if($part===''||$part==='.')continue; if($part==='..'){array_pop($parts);continue;} $parts[]=$part; } return $parts; } function fsFind(DOMElement $root,string $path):?DOMElement{ $parts=fsParts($path); $node=$root; foreach($parts as $part){ if($node->tagName!=='directory')return null; $found=null; foreach($node->childNodes as $child){ if($child instanceof DOMElement&&$child->getAttribute('name')===$part){$found=$child;break;} } if(!$found)return null; $node=$found; } return $node; } function fsParent(DOMElement $root,string $path):array{ $parts=fsParts($path); if(!$parts)return [null,'']; $name=array_pop($parts); $parent=$root; foreach($parts as $part){ $found=null; foreach($parent->childNodes as $child){ if($child instanceof DOMElement&&$child->getAttribute('name')===$part){$found=$child;break;} } if(!$found||$found->tagName!=='directory')return [null,$name]; $parent=$found; } return [$parent,$name]; } function fsExists(DOMElement $parent,string $name):bool{ foreach($parent->childNodes as $child){ if($child instanceof DOMElement&&$child->getAttribute('name')===$name)return true; } return false; } function jsonResponse(array $data):never{ while(ob_get_level())ob_end_clean(); header('Content-Type: application/json; charset=UTF-8'); echo json_encode($data,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES); exit; } if($_SERVER['REQUEST_METHOD']==='POST'){ $raw=file_get_contents('php://input'); $input=json_decode($raw,true); if(!is_array($input))$input=$_POST; $action=(string)($input['action']??''); $path=(string)($input['path']??'/'); $content=(string)($input['content']??''); $dom=fsLoad(); $root=fsRoot($dom); if($action==='list'){ $node=fsFind($root,$path); if(!$node||$node->tagName!=='directory')jsonResponse(['ok'=>false,'error'=>'Dossier introuvable.']); $items=[]; foreach($node->childNodes as $child){ if($child instanceof DOMElement)$items[]=['name'=>$child->getAttribute('name'),'type'=>$child->tagName==='directory'?'directory':'file']; } jsonResponse(['ok'=>true,'items'=>$items]); } if($action==='read'){ $node=fsFind($root,$path); if(!$node||$node->tagName!=='file')jsonResponse(['ok'=>false,'error'=>'Fichier introuvable.']); jsonResponse(['ok'=>true,'content'=>$node->textContent]); } if($action==='mkdir'||$action==='touch'){ [$parent,$name]=fsParent($root,$path); if(!$parent||$name===''||$parent->tagName!=='directory')jsonResponse(['ok'=>false,'error'=>'Dossier parent introuvable.']); if(fsExists($parent,$name))jsonResponse(['ok'=>false,'error'=>'Un élément portant ce nom existe déjà.']); $new=$dom->createElement($action==='mkdir'?'directory':'file'); $new->setAttribute('name',$name); if($action==='touch')$new->appendChild($dom->createTextNode('')); $parent->appendChild($new); if(!fsSave($dom))jsonResponse(['ok'=>false,'error'=>'Impossible d’écrire filesystem.xml.']); jsonResponse(['ok'=>true]); } if($action==='write'){ $node=fsFind($root,$path); if(!$node||$node->tagName!=='file')jsonResponse(['ok'=>false,'error'=>'Fichier introuvable.']); while($node->firstChild)$node->removeChild($node->firstChild); $node->appendChild($dom->createTextNode($content)); if(!fsSave($dom))jsonResponse(['ok'=>false,'error'=>'Impossible d’écrire filesystem.xml.']); jsonResponse(['ok'=>true]); } if($action==='remove'){ $node=fsFind($root,$path); if(!$node||$node===$root)jsonResponse(['ok'=>false,'error'=>'Élément introuvable.']); if($node->tagName==='directory'){ foreach($node->childNodes as $child){ if($child instanceof DOMElement)jsonResponse(['ok'=>false,'error'=>'Le dossier n’est pas vide.']); } } $node->parentNode->removeChild($node); if(!fsSave($dom))jsonResponse(['ok'=>false,'error'=>'Impossible d’écrire filesystem.xml.']); jsonResponse(['ok'=>true]); } jsonResponse(['ok'=>false,'error'=>'Action inconnue.']); } ?> <style> @font-face{font-family:LabsBoot;src:url("font.ttf") format("truetype");font-display:swap} @font-face{font-family:LabsMono;src:url("mono.ttf") format("truetype");font-display:swap} #labs-boot{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;flex-direction:column;background:#000;color:#fff;font-family:LabsBoot,monospace;overflow:hidden} #labs-boot-logo{font-family:LabsBoot,monospace;font-size:clamp(42px,9vw,110px);line-height:1;text-align:center;letter-spacing:2px;animation:bootLogo .9s ease-out both} #labs-boot-subtitle{margin-top:18px;font-family:LabsBoot,monospace;font-size:clamp(12px,2vw,22px);opacity:.7;letter-spacing:2px;animation:bootSub 1s ease-out .2s both} #labs-boot-progress{width:min(420px,65vw);height:5px;margin-top:32px;border:1px solid rgba(255,255,255,.5);overflow:hidden} #labs-boot-progress-bar{width:0;height:100%;background:#fff;transition:width .1s linear} #labs-boot-output{position:absolute;left:20px;right:20px;bottom:18px;max-height:35%;overflow:hidden;font-family:LabsBoot,monospace;font-size:13px;line-height:1.45;text-align:left;opacity:.75;display:none} .labs-boot-line{font-family:LabsBoot,monospace;white-space:pre-wrap} @keyframes bootLogo{from{opacity:0;transform:scale(.9)}to{opacity:1;transform:scale(1)}} @keyframes bootSub{from{opacity:0;transform:translateY(8px)}to{opacity:.7;transform:translateY(0)}} #labs-shell{position:absolute;inset:0;background:#000;color:#fff;display:none;flex-direction:column;font-family:LabsMono,monospace;overflow:hidden} #labs-shell-output{flex:1;overflow:hidden;padding:18px 20px 8px;font-family:LabsMono,monospace;font-size:14px;line-height:1.45;white-space:pre-wrap} #labs-shell-input-line{display:flex;align-items:center;padding:0 20px 18px;font-family:LabsMono,monospace;flex:none} #labs-shell-prompt{font-family:LabsMono,monospace;white-space:nowrap;margin-right:8px} #labs-shell-input{font-family:LabsMono,monospace;flex:1;border:0;outline:0;background:transparent;color:#fff;font-size:14px;padding:0;user-select:text!important;-webkit-user-select:text!important} .shell-command{white-space:pre-wrap} .shell-error{color:#ff5555} .shell-info{opacity:.75} .labs-boot-about{width:100%;height:100%;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;overflow:hidden} .labs-boot-about svg{width:190px;height:190px;flex:none} .labs-boot-about-title{margin-top:8px;font-size:24px} .labs-boot-about-copy{margin-top:6px;font-size:13px} .labs-boot-about-link{margin-top:14px;padding:0;border:0;background:none;color:inherit;font:inherit;cursor:pointer} </style> <div id="labs-boot"> <div id="labs-boot-logo">Labs OS</div> <div id="labs-boot-subtitle">Initialisation du système...</div> <div id="labs-boot-progress"><div id="labs-boot-progress-bar"></div></div> <div id="labs-boot-output"></div> </div> <div id="labs-shell"> <div id="labs-shell-output"></div> <div id="labs-shell-input-line"> <span id="labs-shell-prompt">guest@labs-os:~$</span> <