 0 100 3.306 1.653 1.653 0 000-3.306zm-6.023-3.371a2.48 2.48 0 100 4.96 2.48 2.48 0 000-4.96zM34.058 34.057c-11.548-4.908-17.101 0-17.101 0 0 9.445 7.656 17.102 17.101 17.102s17.101-7.656 17.101-17.102c-.001 0-5.554 4.908-17.101 0z" fill="#b30000"></path> </g> </svg> <div class="labs-boot-about-title">Labs OS</div> <div class="labs-boot-about-copy">© 2026 Survivalier</div> <div class="labs-boot-about-actions"> <button type="button" onclick="window.open('https://survivalier.fast-page.org/labs/labs-os','_blank','noopener,noreferrer')">En savoir plus</button> <button type="button" onclick="LabsOS.hideCard('about')">Fermer</button> </div> </div> </labsos.card> <labsos.card id="credits" title="Crédits"> <div style="width:100%;height:100%;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;overflow:hidden"> <div style="flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;width:100%"> <img src="https://survivalier.fast-page.org/labs/badge.svg" alt="Labs OS" style="max-width:90%;height:auto"> <img src="https://survivalier.fast-page.org/badge.svg" alt="Survivalier" style="max-width:90%;height:auto"> </div> <button type="button" onclick="LabsOS.hideCard('credits')">Fermer</button> </div> </labsos.card> <script> (function(){ "use strict"; const boot=document.getElementById("labs-boot"),progress=document.getElementById("labs-boot-progress-bar"),bootOutput=document.getElementById("labs-boot-output"),shell=document.getElementById("labs-shell"),shellOutput=document.getElementById("labs-shell-output"),shellInput=document.getElementById("labs-shell-input"),shellPrompt=document.getElementById("labs-shell-prompt"); let started=false,bootTimer=null,bootProgress=0,currentPath="/",history=[],historyIndex=-1; function addBootLine(text){ const line=document.createElement("div"); line.className="labs-boot-line"; line.textContent=text; bootOutput.appendChild(line); } async function fsRequest(action,path="/",content=""){ try{ const response=await fetch("boot.php",{method:"POST",headers:{"Content-Type":"application/json","Accept":"application/json"},body:JSON.stringify({action,path,content}),cache:"no-store"}); const text=await response.text(); try{return JSON.parse(text)}catch(e){return{ok:false,error:"Réponse invalide de boot.php."}} }catch(e){return{ok:false,error:"Impossible de contacter boot.php."}} } function print(text,cls){ const line=document.createElement("div"); line.className=cls||"shell-command"; line.textContent=text; shellOutput.appendChild(line); shellOutput.scrollTop=shellOutput.scrollHeight; } function prompt(){ shellPrompt.textContent="guest@labs-os:"+(currentPath==="/"?"~":currentPath)+"$"; } function clearOutput(){ shellOutput.textContent=""; } function normalizePath(path){ path=(path||"/").replace(/\\/g,"/"); let parts=path.startsWith("/")?path.split("/"):currentPath.split("/").concat(path.split("/")),result=[]; for(const part of parts){ if(!part||part===".")continue; if(part==="..")result.pop(); else result.push(part); } return "/"+result.join("/"); } function commandHelp(){ print("Commandes disponibles:"); print("help Affiche cette aide"); print("clear Efface l'écran"); print("echo Affiche un texte"); print("pwd Affiche le chemin actuel"); print("ls Liste les fichiers et dossiers"); print("cd Change de dossier"); print("cat Affiche un fichier"); print("touch Crée un fichier"); print("mkdir Crée un dossier"); print("write Écrit dans un fichier"); print("rm Supprime un fichier"); print("rmdir Supprime un dossier"); print("whoami Affiche l'utilisateur"); print("uname Affiche le système"); print("neofetch Affiche les informations système"); print("history Affiche l'historique"); print("version Affiche la version"); print("about Ouvre les informations de Labs OS"); print("credits Affiche les crédits de Labs OS"); } async function executeCommand(raw){ const line=raw.trim(); if(!line)return; history.push(line); historyIndex=history.length; print("guest@labs-os:"+(currentPath==="/"?"~":currentPath)+"$ "+line); const parts=line.match(/(?:[^\s"]+|"[^"]*")+/g)||[],cmd=(parts.shift()||"").toLowerCase(),args=parts.map(value=>value.replace(/^"(.*)"$/,"$1")); if(["sudo","shutdown","reboot","mkfs","format"].includes(cmd)){ print("Commande désactivée dans Labs OS.","shell-error"); return; } if(cmd==="help"){commandHelp();return} if(cmd==="clear"||cmd==="cls"){clearOutput();return} if(cmd==="echo"){print(args.join(" "));return} if(cmd==="pwd"){print(currentPath);return} if(cmd==="whoami"){print("guest");return} if(cmd==="uname"){print("Labs OS");return} if(cmd==="version"){print("Labs OS 1.0.0");return} if(cmd==="about"){ if(window.LabsOS&&typeof window.LabsOS.showCard==="function"){ if(window.LabsOS.showCard("about"))print("Ouverture de About...","shell-info"); else print("La fenêtre About n'a pas été trouvée.","shell-error"); }else print("API Labs OS indisponible.","shell-error"); return; } if(cmd==="credits"){ if(window.LabsOS&&typeof window.LabsOS.showCard==="function"){ if(window.LabsOS.showCard("credits"))print("Ouverture des crédits...","shell-info"); else print("La fenêtre Crédits n'a pas été trouvée.","shell-error"); }else print("API Labs OS indisponible.","shell-error"); return; }if(cmd==="history"){ history.forEach((value,index)=>print((index+1)+" "+value)); return; } if(cmd==="ls"||cmd==="dir"){ const result=await fsRequest("list",currentPath); if(!result.ok){print(result.error,"shell-error");return} if(!result.items.length){print("(vide)");return} print(result.items.map(item=>item.type==="directory"?item.name+"/":item.name).join(" ")); return; } if(cmd==="cd"){ const target=normalizePath(args[0]||"/"),result=await fsRequest("list",target); if(!result.ok){print("Dossier introuvable.","shell-error");return} currentPath=target; prompt(); return; } if(cmd==="cat"){ if(!args[0]){print("Usage: cat <fichier>","shell-error");return} const result=await fsRequest("read",normalizePath(args[0])); if(!result.ok){print(result.error,"shell-error");return} print(result.content||""); return; } if(cmd==="touch"){ if(!args[0]){print("Usage: touch <fichier>","shell-error");return} const result=await fsRequest("touch",normalizePath(args[0])); if(!result.ok)print(result.error,"shell-error"); else print("Fichier créé.","shell-info"); return; } if(cmd==="mkdir"){ if(!args[0]){print("Usage: mkdir <dossier>","shell-error");return} const result=await fsRequest("mkdir",normalizePath(args[0])); if(!result.ok)print(result.error,"shell-error"); else print("Dossier créé.","shell-info"); return; } if(cmd==="write"){ if(args.length<2){print("Usage: write <fichier> <texte>","shell-error");return} const file=args.shift(),result=await fsRequest("write",normalizePath(file),args.join(" ")); if(!result.ok)print(result.error,"shell-error"); else print("Fichier modifié.","shell-info"); return; } if(cmd==="rm"||cmd==="rmdir"){ if(!args[0]){print("Usage: "+cmd+" <élément>","shell-error");return} const result=await fsRequest("remove",normalizePath(args[0])); if(!result.ok)print(result.error,"shell-error"); else print("Élément supprimé.","shell-info"); return; } if(cmd==="neofetch"){ print("██"); print("██████ Labs OS"); print("████████ Version: 1.0.0"); print("████████ User: guest"); print("████████ Shell: LabsShell"); print("██████ Path: "+currentPath); print("██"); return; } print("Commande inconnue : "+cmd,"shell-error"); } function startShell(){ if(started)return; started=true; boot.style.display="none"; shell.style.display="flex"; print("Labs OS Shell"); print("Système de fichiers : filesystem.xml","shell-info"); print("Tapez « help » pour afficher les commandes.","shell-info"); prompt(); shellInput.blur(); } function startBoot(){ if(bootTimer)return; bootProgress=0; progress.style.width="0%"; bootOutput.innerHTML=""; bootOutput.style.display="block"; addBootLine("[ OK ] Initialisation de Labs OS"); bootTimer=setInterval(function(){ bootProgress+=2.5; if(bootProgress>100)bootProgress=100; progress.style.width=bootProgress+"%"; if(bootProgress===25)addBootLine("[ OK ] Chargement du noyau"); if(bootProgress===50)addBootLine("[ OK ] Lecture de filesystem.xml"); if(bootProgress===75)addBootLine("[ OK ] Démarrage du shell"); if(bootProgress>=100){ clearInterval(bootTimer); bootTimer=null; setTimeout(startShell,350); } },70); } shellInput.addEventListener("keydown",function(event){ if(event.key==="Enter"){ const value=shellInput.value; shellInput.value=""; executeCommand(value); return; } if(event.key==="ArrowUp"){ event.preventDefault(); if(historyIndex>0){ historyIndex--; shellInput.value=history[historyIndex]; } return; } if(event.key==="ArrowDown"){ event.preventDefault(); if(historyIndex<history.length-1){ historyIndex++; shellInput.value=history[historyIndex]; }else{ historyIndex=history.length; shellInput.value=""; } } }); window.LabsOSBoot={start:startBoot,pause:function(){},resume:function(){}}; })(); </script>